// Helper to get local image URL with fallback
export function getLocalImage(originalUrl: string): string {
  // Try exact match first
  if (IMAGE_MAP[originalUrl]) return IMAGE_MAP[originalUrl];
  
  // Try without query params (base URL)
  const base = originalUrl.split('?')[0];
  if (IMAGE_MAP[base]) return IMAGE_MAP[base];
  
  // Try matching by photo ID
  const match = originalUrl.match(/photo-(\d+)/);
  if (match) {
    const photoId = match[1];
    for (const [key, value] of Object.entries(IMAGE_MAP)) {
      if (key.includes(`photo-${photoId}`)) return value;
    }
  }
  
  // Fallback to a default
  return "/images/demo-01.jpg";
}

// Remove emojis de strings de texto
export function stripEmojis(text: string): string {
  return text.replace(/([\u2700-\u27BF]|[\uE000-\uF8FF]|\uD83C[\uDC00-\uDFFF]|\uD83D[\uDC00-\uDFFF]|[\u2011-\u26FF]|\uD83E[\uDD10-\uDDFF])/g, '').trim();
}